import{_ as a,o as n,c as i,ag as l}from"./chunks/framework.CmaAMB6e.js";const c=JSON.parse('{"title":"22 · 数据库高可用","description":"","frontmatter":{"概念":"数据库高可用","技能":"database","阶段":"5-资深层","状态":"⬜未开始","更新日期":"2026-08-01T00:00:00.000Z"},"headers":[],"relativePath":"database/concepts/22-high-availability.md","filePath":"database/concepts/22-high-availability.md","lastUpdated":null}'),p={name:"database/concepts/22-high-availability.md"};function t(e,s,h,r,k,o){return n(),i("div",null,[...s[0]||(s[0]=[l(`<h1 id="_22-·-数据库高可用" tabindex="-1">22 · 数据库高可用 <a class="header-anchor" href="#_22-·-数据库高可用" aria-label="Permalink to &quot;22 · 数据库高可用&quot;">​</a></h1><h2 id="概念简介" tabindex="-1">概念简介 <a class="header-anchor" href="#概念简介" aria-label="Permalink to &quot;概念简介&quot;">​</a></h2><p>单机数据库一旦宕机，业务全线停摆。<strong>高可用（HA）<strong>的目标是：把「数据库挂掉」从事故变成流程——通过</strong>主从复制</strong>保存多份数据副本，通过<strong>读写分离</strong>把查询压力分散到从库，通过<strong>故障切换</strong>在主机挂掉后几十秒内自动把从库提升为主库，让业务几乎无感。这不是「备份」，备份是兜底数据，高可用是兜底<strong>可用性</strong>，两者都要有。</p><p>核心手段是复制。MySQL 的主从复制基于 <strong>binlog（二进制日志）</strong>：主库把每次数据变更写进 binlog，从库拉取并在自己机器上重放，得到与主库相同的数据。理解复制原理，是高可用的第一步——延迟、断链、脑裂都从这里来。</p><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><h4 id="_1-主从复制原理-binlog-复制链路" tabindex="-1">1. 主从复制原理：binlog 复制链路 <a class="header-anchor" href="#_1-主从复制原理-binlog-复制链路" aria-label="Permalink to &quot;1. 主从复制原理：binlog 复制链路&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># ---------- MySQL 异步复制链路(一主一从) ----------</span></span>
<span class="line"><span># 主库:   应用线程执行事务 -&gt; 写 binlog -&gt; 事务提交</span></span>
<span class="line"><span># 从库:   ① IO 线程 从主库拉取 binlog 并写入本地 relay log(中继日志)</span></span>
<span class="line"><span>#         ② SQL 线程 重放 relay log,在主库那边回放成同样的数据变更</span></span>
<span class="line"><span># 关键点:IO 线程和 SQL 线程是异步的 —— 主库提交后不等待从库,</span></span>
<span class="line"><span>#        所以「从库数据永远可能比主库旧一点点」,这就是主从延迟的根源</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ---------- 主库配置(my.cnf) ----------</span></span>
<span class="line"><span>[mysqld]</span></span>
<span class="line"><span>server-id = 1            # 每个实例唯一,复制链路按 server-id 区分</span></span>
<span class="line"><span>log-bin = mysql-bin      # 开启 binlog(主从复制的前提,也是备份/恢复的底子)</span></span>
<span class="line"><span>binlog-format = ROW      # 行格式:记录每行变更,数据一致性好(比 STATEMENT 安全)</span></span>
<span class="line"><span>binlog-row-image = FULL</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ---------- 从库配置(my.cnf) ----------</span></span>
<span class="line"><span>[mysqld]</span></span>
<span class="line"><span>server-id = 2</span></span>
<span class="line"><span>log-bin = mysql-bin</span></span>
<span class="line"><span>relay-log = mysql-relay-bin</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ---------- 主库创建复制账号,并授权从库拉取 binlog ----------</span></span>
<span class="line"><span>CREATE USER &#39;repl&#39;@&#39;%&#39; IDENTIFIED BY &#39;强密码&#39;;</span></span>
<span class="line"><span>GRANT REPLICATION SLAVE ON *.* TO &#39;repl&#39;@&#39;%&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ---------- 从库初始化复制链路 ----------</span></span>
<span class="line"><span>CHANGE MASTER TO</span></span>
<span class="line"><span>  MASTER_HOST = &#39;10.0.0.1&#39;,        -- 主库 IP</span></span>
<span class="line"><span>  MASTER_USER = &#39;repl&#39;,</span></span>
<span class="line"><span>  MASTER_PASSWORD = &#39;强密码&#39;,</span></span>
<span class="line"><span>  MASTER_LOG_FILE = &#39;mysql-bin.000123&#39;,   -- 从主库 SHOW MASTER STATUS 拿到</span></span>
<span class="line"><span>  MASTER_LOG_POS = 45678;</span></span>
<span class="line"><span>START SLAVE;</span></span></code></pre></div><h4 id="_2-读写分离-主库写、从库读" tabindex="-1">2. 读写分离：主库写、从库读 <a class="header-anchor" href="#_2-读写分离-主库写、从库读" aria-label="Permalink to &quot;2. 读写分离：主库写、从库读&quot;">​</a></h4><p>复制搭好之后，应用层把写请求发给主库、读请求发给从库：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># ---------- 读写分离架构 ----------</span></span>
<span class="line"><span># 应用 -&gt; 路由层(中间件如 ProxySQL / ShardingSphere,或应用内数据源双配置)</span></span>
<span class="line"><span>#         -&gt; 写请求(INSERT/UPDATE/DELETE): 发主库</span></span>
<span class="line"><span>#         -&gt; 读请求(SELECT):               轮询发从库,可加权</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># 收益:主库只扛写入,从库扛住 80% 以上的读流量,整体吞吐翻几倍</span></span>
<span class="line"><span># 代价:从库有延迟,刚写入的数据读从库可能读不到 —— 这叫「读写不一致」</span></span></code></pre></div><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 处理读写不一致的常见方案:关键数据强读主库</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 场景:用户下单成功后立刻查「我的订单」</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> orders </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DESC</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> LIMIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 如果走从库,可能查不到刚下的单(从库还没重放到这条 binlog)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 方案1:下单后 1 秒内的读强制走主库(按时间窗)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 方案2:前端交互天然有时差(下单成功页停留几秒),多数场景可接受</span></span></code></pre></div><h4 id="_3-半同步复制-牺牲一点性能换不丢数据" tabindex="-1">3. 半同步复制：牺牲一点性能换不丢数据 <a class="header-anchor" href="#_3-半同步复制-牺牲一点性能换不丢数据" aria-label="Permalink to &quot;3. 半同步复制：牺牲一点性能换不丢数据&quot;">​</a></h4><p>异步复制下，主库提交后从库还没拉到 binlog，此时主库宕机——从库上没有这条数据，数据丢了。<strong>半同步复制（semi-sync）</strong> 让主库提交前至少等一个从库确认「binlog 已收到」，从而保证主库挂了数据也已在从库手上：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 安装半同步插件(MySQL 5.7+ 自带,主从都要装)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">INSTALL PLUGIN rpl_semi_sync_master SONAME </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;semisync_master.so&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">INSTALL PLUGIN rpl_semi_sync_slave  SONAME </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;semisync_slave.so&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 主库开启半同步,并设置等待超时</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> GLOBAL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rpl_semi_sync_master_enabled </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> GLOBAL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rpl_semi_sync_master_timeout </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 3 秒内无从库确认就退回异步,保证主库不卡死</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 从库开启半同步</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> GLOBAL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rpl_semi_sync_slave_enabled </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">STOP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SLAVE; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">START</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SLAVE;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 重载后生效</span></span></code></pre></div><p><strong>代价</strong>：每次提交都要等网络往返，延迟上升（主从跨机房时尤其明显）。半同步是「性能 vs 不丢数据」的折中，生产标配。</p><h4 id="_4-故障切换-mha-orchestrator" tabindex="-1">4. 故障切换：MHA / Orchestrator <a class="header-anchor" href="#_4-故障切换-mha-orchestrator" aria-label="Permalink to &quot;4. 故障切换：MHA / Orchestrator&quot;">​</a></h4><p>主机宕机后，需要自动化地：检测故障 → 从从库中选出数据最完整的一台 → 提升为主库 → 把其他从库重新挂到新主库 → 通知应用切换连接。这一步叫 <strong>failover</strong>，人工执行会按分钟算，自动化工具能压到几十秒。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ---------- Orchestrator(推荐,提供 API 和 Web UI,业界广泛使用) ----------</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 安装后启动 agent,节点间通过心跳互相发现</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orchestrator</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 10.0.0.1:3306</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 注册主库</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orchestrator</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 10.0.0.2:3306</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 注册从库</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 主库宕机后,人工确认/自动触发切换:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#   orchestrator 自动做:选新主 -&gt; 补齐缺失的 binlog -&gt; 提升 -&gt; 重挂从库</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orchestrator</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> graceful-master-takeover</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --failover</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 10.0.0.1:3306</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ---------- 应用层配合:切换后连接目标变了 ----------</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 数据库地址不能写死在应用配置里,应走 DNS / 注册中心 / 代理</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 切换时只需改 DNS A 记录指向新主库,应用自动生效</span></span></code></pre></div><p><strong>脑裂问题</strong>：网络抖动时新旧主库可能同时认为自己是主，出现「双主」各写各的——必须靠**仲裁（quorum）**机制：切换需要超过半数节点（或外部仲裁者）确认主库真的死了才动手，并把旧主库强制下线（fencing，如用 <code>SET GLOBAL read_only=ON</code> 拒绝旧主写入）。</p><h4 id="_5-多机房容灾" tabindex="-1">5. 多机房容灾 <a class="header-anchor" href="#_5-多机房容灾" aria-label="Permalink to &quot;5. 多机房容灾&quot;">​</a></h4><p>单机房故障（断电/网络切割）会让整条主从链一起挂。多机房容灾的常见布局：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># ---------- 两地三中心 / 同城双活布局 ----------</span></span>
<span class="line"><span># 机房A(主):  主库 + 从库1  —— 应用主力流量</span></span>
<span class="line"><span># 机房B(备):  从库2          —— 实时复制,同城专线延迟 &lt; 5ms,可做双活读</span></span>
<span class="line"><span># 机房C(远):  从库3          —— 跨城异步复制(专线不稳),只做灾备,平时不读</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># 容灾等级:</span></span>
<span class="line"><span>#   机房A 挂 -&gt; 提升机房B 从库2 为主,业务切换读流量(秒级~分钟级)</span></span>
<span class="line"><span>#   机房A+B 同时挂 -&gt; 机房C 数据最旧但最安全,恢复服务(数据可能丢几十秒)</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># 关键矛盾:复制链路越远越不稳,跨城一般只做异步复制</span></span>
<span class="line"><span>#         —— 所以要接受「异地容灾可丢最后几秒数据」的现实</span></span></code></pre></div><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ul><li><strong>把备份当成高可用</strong>：备份只能救数据，恢复要小时级；主从是救可用性，切换是秒级。两者缺一不可，别用备份替代复制。</li><li><strong>忽略主从延迟</strong>：做了读写分离但没评估延迟，刚写的订单查不到——对账、刷单检测等场景必须强读主库或延迟敏感查询走主库。</li><li><strong>半同步跨机房部署</strong>：半同步要求主库提交前等从库确认，跨机房专线抖动会直接把主库拖死，超时设太小会频繁退回异步导致数据保护形同虚设。</li><li><strong>切换后应用还在连旧主库</strong>：连接串写死 IP、连接池缓存了旧连接——failover 必须配套 DNS/代理/注册中心，且连接池要能感知断连重连。</li><li><strong>脑裂不设防</strong>：没有仲裁/锁，双主同时写导致数据错乱；旧主必须被强制只读并切断应用流量（fencing）。</li><li><strong>从库性能不达标</strong>：从库承担全部读流量后先崩——从库要单独做容量规划，复制线程重放慢时优先排查大事务、DDL 在从库的锁等待。</li></ul><h2 id="练习建议" tabindex="-1">练习建议 <a class="header-anchor" href="#练习建议" aria-label="Permalink to &quot;练习建议&quot;">​</a></h2><ol><li><strong>基础</strong>：用 Docker 起一主两从 MySQL（官方镜像即可），手写 CHANGE MASTER 配好复制，验证主库 INSERT 后从库能查到，并观察 <code>SHOW SLAVE STATUS</code> 的 <code>Seconds_Behind_Master</code> 字段。</li><li><strong>进阶</strong>：开启半同步，对比开关前后的写入延迟；再用一个大事务（如一次性 UPDATE 一百万行）制造复制延迟，观察读写分离下「读不到刚写入数据」的真实效果。</li><li><strong>综合</strong>：模拟主库宕机（<code>docker kill</code> 主库容器），手动完成一次故障切换：选从、补齐 binlog、提升、重挂从库，记录每一步的命令和耗时，写出你自己的切换 checklist。</li></ol><blockquote><p>用 <code>/practice database 数据库高可用</code> 生成更多针对性练习。</p></blockquote><h2 id="前端对照" tabindex="-1">前端对照 <a class="header-anchor" href="#前端对照" aria-label="Permalink to &quot;前端对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前端</th><th>数据库高可用</th></tr></thead><tbody><tr><td>CDN 多节点分发</td><td>主从复制（多份数据副本）</td></tr><tr><td>DNS 切流 / 负载均衡器健康检查</td><td>故障切换（failover）</td></tr><tr><td>静态资源打包加版本号（缓存失效）</td><td>binlog 从主库同步到从库（变更传播）</td></tr><tr><td>前端灰度发布：新旧版本并存</td><td>一主多从：新数据在主、旧数据在从</td></tr><tr><td>部署多实例做水平扩展</td><td>读写分离（从库扛读流量）</td></tr></tbody></table><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h2><ul><li><a href="https://dev.mysql.com/doc/refman/8.0/en/replication.html" target="_blank" rel="noreferrer">MySQL 官方文档：复制（Replication）</a></li><li><a href="https://dev.mysql.com/doc/refman/8.0/en/replication-semisync.html" target="_blank" rel="noreferrer">MySQL 官方文档：半同步复制</a></li><li><a href="https://github.com/openark/orchestrator" target="_blank" rel="noreferrer">Orchestrator 官方文档</a></li><li><a href="https://github.com/yoshinorim/mha4mysql-manager" target="_blank" rel="noreferrer">MHA（Master High Availability）文档</a></li></ul>`,31)])])}const g=a(p,[["render",t]]);export{c as __pageData,g as default};
